import { deduceMeshField } from '@loaders.gl/schema';
import { Schema } from '@loaders.gl/schema';
export function getDracoSchema(attributes, loaderData, indices) {
  var metadataMap = makeMetadata(loaderData.metadata);
  var fields = [];
  var namedLoaderDataAttributes = transformAttributesLoaderData(loaderData.attributes);

  for (var attributeName in attributes) {
    var attribute = attributes[attributeName];
    var field = getArrowFieldFromAttribute(attributeName, attribute, namedLoaderDataAttributes[attributeName]);
    fields.push(field);
  }

  if (indices) {
    var indicesField = getArrowFieldFromAttribute('indices', indices);
    fields.push(indicesField);
  }

  return new Schema(fields, metadataMap);
}

function transformAttributesLoaderData(loaderData) {
  var result = {};

  for (var key in loaderData) {
    var dracoAttribute = loaderData[key];
    result[dracoAttribute.name || 'undefined'] = dracoAttribute;
  }

  return result;
}

function getArrowFieldFromAttribute(attributeName, attribute, loaderData) {
  var metadataMap = loaderData ? makeMetadata(loaderData.metadata) : undefined;
  var field = deduceMeshField(attributeName, attribute, metadataMap);
  return field;
}

function makeMetadata(metadata) {
  var metadataMap = new Map();

  for (var key in metadata) {
    metadataMap.set("".concat(key, ".string"), JSON.stringify(metadata[key]));
  }

  return metadataMap;
}